function searchYaku(query = "", group = "全部") {
  const q = String(query).trim().toLowerCase();
  return YAKU.filter(
    (y) =>
      (group === "全部" || y.group === group) &&
      (!q || (y.name + y.description).toLowerCase().includes(q)),
  );
}

module.exports = { YAKU, searchYaku };
